def eq_1_sigma(Q_k, T, c):
    """\\sigma(k, c) = \\frac{2}{\\sqrt{T}} Q_k^{-1} \\left( \\frac{1+c}{2} \\right).

    Formula f7, page 2, section '1 Introduction', equation (1). Returns the right-hand side (sigma(…) = …).

    Variables:
        c: the call
    """
    return 2*((1/2)*c + 1/2)/(Q_k*math.sqrt(T))


def eq_3_c_BS(Phi, k, v):
    """c_{BS}(k, v) = \\Phi\\left(-\\frac{k}{v} + \\frac{v}{2}\\right) - e^k \\Phi\\left(-\\frac{k}{v} - \\frac{v}{2}\\right).

    Formula f21, page 4, section '2 Implied Volatility is a Quantile', equation (3). Returns the right-hand side (c_BS(…) = …). Phi, Phi(…) read as a product.
    """
    return -Phi*(-k/v - 1/2*v)*math.exp(k) + Phi*(-k/v + (1/2)*v)


def eq_8(c, k, p):
    """c - p = 1 - e^k.

    Formula f43, page 5, section '2 Implied Volatility is a Quantile', equation (8). Returns lhs - rhs (zero when the equation holds).

    Variables:
        c: the call
    """
    return c - p + math.exp(k) - 1


def eq_23(c_k, q_kk, q_ku, q_u, q_uu, w_kk):
    """w_{kk} \\geq q_{kk} + 2q_{ku}c_k + q_{uu}c_k^2 + q_uc_k.

    Formula f123, page 9, section '3.3 No-arbitrage in Variance-Space', equation (23). Returns whether the relation holds.

    Variables:
        c_k: the observed surface expresses
        w_kk: the implied-variance curvature
    """
    return (w_kk >= c_k**2*q_uu + 2*c_k*q_ku + c_k*q_u + q_kk)


def eq_27_k(Delta, Phi, v):
    """k = v \\left( \\frac{v}{2} - \\Phi^{-1}(\\Delta) \\right).

    Formula f142, page 11, section '4 Numerical Evaluation', equation (27). Returns the right-hand side (k = …).
    """
    return v(-Delta/Phi + (1/2)*v)


def eq_37_f_k(k, pi, w):
    """f_k(w) = \\frac{e^{k/2}}{2\\sqrt{2\\pi}} w^{-1/2} \\exp\\left(-\\frac{w}{8} - \\frac{k^2}{2w}\\right), \\quad w > 0.

    Formula f226, page 20, section 'A.2 The Quantile is not D-finite', equation (37). Returns the right-hand side (f_k(…) = …). Text after the last top-level comma was ignored.

    Variables:
        w: derivatives of the observed surfaces
    """
    return (1/4)*math.sqrt(2)*math.exp((1/2)*k)*math.exp(-1/2*k**2/w - 1/8*w)/(math.sqrt(pi)*math.sqrt(w))


def eq_40(c, k, o, pi, w):
    """\\log \\frac{1}{c} = \\frac{k^2}{2w} - \\frac{3}{2} \\log w + \\log \\left( \\frac{k^2 \\sqrt{2\\pi}}{e^{k/2}} \\right) + o(1), \\quad w \\downarrow 0.

    Formula f237, page 21, section 'A.2 The Quantile is not D-finite', equation (40). Returns lhs - rhs (zero when the equation holds). Text after the last top-level comma was ignored.

    Variables:
        c: the call
        w: derivatives of the observed surfaces
    """
    return -1/2*k**2/w - o(1) + math.log(1/c) + (3/2)*math.log(w) - math.log(math.sqrt(2)*k**2*math.sqrt(pi)*math.exp(-1/2*k))


def f241(c, k, w):
    """\\log \\frac{1}{c} = \\frac{k^2}{2w} + O\\left(\\log \\log \\frac{1}{c}\\right),

    Formula f241, page 21, section 'A.2 The Quantile is not D-finite'. Returns lhs - rhs (zero when the equation holds). O(…) remainder terms were dropped.

    Variables:
        c: the call
        w: derivatives of the observed surfaces
    """
    return -1/2*k**2/w + math.log(1/c)


def eq_41_w(c, k):
    """w(c) = \\frac{k^2}{2 \\log(1/c)} \\left( 1 + O\\left( \\frac{\\log \\log(1/c)}{\\log(1/c)} \\right) \\right), \\quad c \\downarrow 0.

    Formula f243, page 21, section 'A.2 The Quantile is not D-finite', equation (41). Returns the right-hand side (w(…) = …). O(…) remainder terms were dropped. Text after the last top-level comma was ignored.

    Variables:
        c: the call
    """
    return (1/2)*k**2/math.log(1/c)

